Lemma shrinkW_eq : forall szc k c, 0 <= c <= 32 -> 1 <= szc <= 8191 ->
  shrinkW (Z_to_bv 64 (16 * szc)) k (Z_to_bv 64 c) = Z_to_bv 64 (shrink k (16 * szc) c) /\
  0 <= shrink k (16 * szc) c <= 32.
Proof.
