Definition chk_small_in (sc : Z) : bool :=
  inb (small_cnt (3 * sc)) (cnt_cands sc) && inb (small_cnt (3 * sc + 1)) (cnt_cands sc) && inb (small_cnt (3 * sc + 2)) (cnt_cands sc)
  && (small_cnt (3 * sc) <=? 32) && (small_cnt (3 * sc + 1) <=? 32) && (small_cnt (3 * sc + 2) <=? 32).
