Section Cnt.
  Context {R : Type}.
  Implicit Types (s : mstate) (P : R -> mstate -> Prop).

  Theorem ts_alloc_cnt : forall s (sc : Z) (usage : word) (k : word -> M R) P,
    rodata_clear (ms_mem s) -> WIN s -> 0 <= sc < 48 ->
    (forall c, In c (cnt_cands sc) -> 1 <= c <= 32 -> tsafe (k (Z_to_bv 64 c) s) P) ->
